themes.css:
/* 默认样式，最佳实践 */

/* 全局属性 */
#wemd {
  font-size: 16px;
  color: #000000;
  padding: 0 8px;
  line-height: 1.6;
  word-spacing: 0px;
  letter-spacing: 0px;
  word-break: break-word;
  word-wrap: break-word;
  text-align: left;
  font-family: Optima-Regular, Optima, PingFangSC-light, PingFangTC-light, 'PingFang SC', 'Microsoft YaHei', '微软雅黑', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

/* 段落 */
#wemd p {
  font-size: 16px;
  margin: 0;
  line-height: 26px;
  color: #000000;
}

/* 标题 */
#wemd h1,
#wemd h2,
#wemd h3,
#wemd h4,
#wemd h5,
#wemd h6 {
  margin-top: 30px;
  margin-bottom: 15px;
  padding: 0px;
  font-weight: bold;
  color: #000000;
}
#wemd h1 {
  font-size: 24px;
}
#wemd h2 {
  font-size: 22px;
}
#wemd h3 {
  font-size: 20px;
}
#wemd h4 {
  font-size: 18px;
}
#wemd h5 {
  font-size: 16px;
}
#wemd h6 {
  font-size: 16px;
}

#wemd h1 .prefix,
#wemd h2 .prefix,
#wemd h3 .prefix,
#wemd h4 .prefix,
#wemd h5 .prefix,
#wemd h6 .prefix {
  display: none;
}

#wemd h1 .suffix,
#wemd h2 .suffix,
#wemd h3 .suffix,
#wemd h4 .suffix,
#wemd h5 .suffix,
#wemd h6 .suffix {
  display: none;
}

/* 列表 */
#wemd ul,
#wemd ol {
  margin-top: 8px;
  margin-bottom: 8px;
  padding-left: 25px;
  color: #000000;
}
#wemd ul {
  list-style-type: disc;
}
#wemd ul ul {
  list-style-type: square;
}

#wemd ol {
  list-style-type: decimal;
}

#wemd li section {
  margin-top: 5px;
  margin-bottom: 5px;
  line-height: 26px;
  text-align: left;
  color: #010101; /* 使用接近黑色的 HEX，避免微信吞掉纯黑色 */
  font-weight: 500;
}

/* 引用 */
#wemd blockquote {
  border: none;
}

#wemd .multiquote-1 {
  display: block;
  font-size: 0.9em;
  overflow: auto;
  overflow-scrolling: touch;
  border-left: 3px solid rgba(0, 0, 0, 0.4);
  background: rgba(0, 0, 0, 0.05);
  color: #6a737d;
  padding-top: 10px;
  padding-bottom: 10px;
  padding-left: 20px;
  padding-right: 10px;
  margin-bottom: 20px;
  margin-top: 20px;
}

#wemd .multiquote-1 p {
  margin: 0px;
  color: #000000;
  line-height: 26px;
}

#wemd .multiquote-2 {
  box-shadow: 1px 1px 10px rgba(0,0,0,0.2);
  padding: 20px;
  margin-bottom: 20px;
  margin-top: 20px;
}

#wemd .multiquote-3 {
  box-shadow: 1px 1px 10px rgba(0,0,0,0.2);
  padding: 20px;
  margin-bottom: 20px;
  margin-top: 20px;
}

#wemd .multiquote-3 p {
  text-align: center;
}

#wemd .multiquote-3 h3 {
  text-align: center;
}

#wemd .table-of-contents a {
  border: none;
  color: #000000;
  font-weight: normal;
}

/* 链接 */
#wemd a {
  text-decoration: none;
  color: #1e6bb8;
  word-wrap: break-word;
  font-weight: bold;
  border-bottom: 1px solid #1e6bb8;
}

/* 加粗 */
#wemd strong {
  font-weight: bold;
  color: #000000;
}

/* 斜体 */
#wemd em {
  font-style: italic;
  color: #000000;
}

/* 加粗斜体 */
#wemd em strong {
  font-weight: bold;
  color: #000000;
}

/* 删除线 */
#wemd del {
  font-style: italic;
  color: #000000;
}

/* 下划线 */
#wemd u {
  text-decoration: underline;
  text-underline-offset: 0.18em;
  text-decoration-thickness: 1px;
}

/* 分隔线 */
#wemd hr {
  height: 1px;
  margin: 0;
  margin-top: 10px;
  margin-bottom: 10px;
  border: none;
  border-top: 1px solid black;
}

/* 代码块容器 */
#wemd pre {
  margin-top: 10px;
  margin-bottom: 10px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

#wemd pre.custom {
  padding: 0;
  border-radius: 6px;
  overflow: hidden;
  overflow-x: auto;
}

#wemd pre code {
  display: block;
  font-family: Operator Mono, Consolas, Monaco, Menlo, monospace;
  border-radius: 0px;
  font-size: 12px;
  white-space: pre;
  min-width: max-content;
  -webkit-overflow-scrolling: touch;
}

#wemd pre code span {
  line-height: 26px;
}

/* 行内代码 */
#wemd p code,
#wemd li code {
  font-size: 14px;
  word-wrap: break-word;
  padding: 2px 4px;
  border-radius: 4px;
  margin: 0 2px;
  color: #1e6bb8;
  background-color: rgba(27,31,35,.05);
  font-family: Operator Mono, Consolas, Monaco, Menlo, monospace;
  word-break: break-all;
}

/* 图片 */
#wemd img {
  display: block;
  margin: 0 auto;
  max-width: 100%;
}

/* 图片 */
#wemd figure {
  margin: 0;
  margin-top: 10px;
  margin-bottom: 10px;
}

/* 图片描述文字 */
#wemd figcaption {
  margin-top: 5px;
  text-align: center;
  color: #888;
  font-size: 14px;
}


/* 表格容器 */
#wemd .table-container{
  overflow-x: auto;
}

/* 表格 */
#wemd table {
  display: table;
  text-align: left;
}
#wemd tbody {
  border: 0;
}

#wemd table tr {
  border: 0;
  border-top: 1px solid #ccc;
  background-color: #ffffff;
}

#wemd table tr:nth-child(2n) {
  background-color: #F8F8F8;
}

#wemd table tr th,
#wemd table tr td {
  font-size: 16px;
  border: 1px solid #ccc;
  padding: 5px 10px;
  text-align: left;
}

#wemd table tr th {
  font-weight: bold;
  background-color: #f0f0f0;
}

/* 表格最小列宽4个汉字 */
#wemd table tr th:nth-of-type(n),
#wemd table tr td:nth-of-type(n){
  min-width:85px;
}

#wemd .footnote-word {
  color: #1e6bb8;
  font-weight: bold;
}

#wemd .footnote-ref {
  color: #1e6bb8;
  font-weight: bold;
}

#wemd .footnote-item {
  display: flex;
}

#wemd .footnote-num {
  display: inline;
  width: 10%; /*神奇，50px就不可以*/
  background: none;
  font-size: 80%;
  opacity: 0.6;
  line-height: 26px;
  font-family: ptima-Regular, Optima, PingFangSC-light, PingFangTC-light, 'PingFang SC', Cambria, Cochin, Georgia, Times, 'Times New Roman', serif;
}

#wemd .footnote-item p {
  display: inline;
  font-size: 14px;
  width: 90%;
  padding: 0px;
  margin: 0;
  line-height: 26px;
  color: #000000;
  word-break:break-all;
  width: calc(100%-50)
}

#wemd sub, sup {
  line-height: 0;
}

#wemd .footnotes-sep:before {
  content: "参考资料";
  display: block;
}

/* 解决公式问题 */
#wemd .block-equation {
  display:block;
  text-align: center;
  overflow: auto;
  display: block;
  -webkit-overflow-scrolling: touch;
}

#wemd .block-equation > svg {
  max-width: 300% !important;
  -webkit-overflow-scrolling: touch;
}

#wemd .inline-equation {
}

#wemd .inline-equation > svg {
}

#wemd .imageflow-layer1 {
  margin-top: 1em;
  margin-bottom: 0.5em;
  white-space: normal;
  border: 0px none;
  padding: 0px;
  overflow: hidden;
}

#wemd .imageflow-layer2 {
  white-space: nowrap;
  width: 100%;
  overflow-x: scroll;
}

#wemd .imageflow-layer3 {
  display: inline-block;
  word-wrap: break-word;
  white-space: normal;
  vertical-align: top;
  width: 80%;
  margin-right: 10px;
  flex-shrink: 0;
}

#wemd .imageflow-img {
  display: block;
  width: 100%;
  height: auto;
  max-height: 300px;
  object-fit: contain;
  border-radius: 4px;
}

#wemd .imageflow-caption {
  text-align: center;
  margin-top: 0px;
  padding-top: 0px;
  color: #888;
}

#wemd .nice-suffix-juejin-container {
  margin-top: 20px !important;
}

#wemd figure a {
  border: none;
}

#wemd figure a img {
  margin: 0px;
}

#wemd figure {
  display:flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

/* 图片链接嵌套 */
#wemd figure a {
  display: flex;
  justify-content: center;
  align-items: center;
}

/* 图片链接嵌套，图片解释 */
#wemd figure a + figcaption {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  margin-top: -35px;
  background: rgba(0,0,0,0.7);
  color: #ffffff;
  line-height: 35px;
  z-index: 20;
}

#wemd .callout {
  margin: 24px 0;
  padding: 18px 20px;
  border-radius: 16px;
  border: 1px solid #e2e8f0;
  background: #ffffff;
  box-shadow: 0 12px 25px rgba(15, 23, 42, 0.08);
}

#wemd .callout-title {
  font-weight: 600;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 0;
  letter-spacing: 0.05em;
}

#wemd .callout-icon { margin-right: 8px;
  font-size: 18px;
}

#wemd .callout-note { border-left: 4px solid #6366f1; background: #f5f5ff; }
#wemd .callout-tip { border-left: 4px solid #10b981; background: #ecfdf5; }
#wemd .callout-important { border-left: 4px solid #8b5cf6; background: #f5f3ff; }
#wemd .callout-warning { border-left: 4px solid #f59e0b; background: #fffbeb; }
#wemd .callout-caution { border-left: 4px solid #ef4444; background: #fff5f5; }


#wemd .task-list-item {
  list-style: none;
  margin-left: -1.2em;
  margin-bottom: 6px;
  display: flex;
  gap: 0;
  align-items: flex-start;
}

#wemd .task-list-item input[type='checkbox'] {
  margin-top: 4px;
  pointer-events: none;
}

/* 学术论文风格 */
#wemd {
    padding: 5px 20px;
    max-width: 677px;
    margin: 0 auto;
    /* 混合字体栈：西文Times + 中文宋体 */
    font-family: "Times New Roman", "Songti SC", "SimSun", serif;
    color: #000;
    background-color: transparent;
    /* 透明背景，兼容微信深色模式 */
    word-break: break-word;
}

/* 正文 - 移除首行缩进，改用段间距适应移动端 */
#wemd p {
    margin: 16px 0;
    line-height: 1.7;
    text-align: justify;
    text-indent: 0;
    color: #1a1a1a;
    font-size: 16px;
}

/* 一级标题 - 居中论文题 */
#wemd h1 {
    margin: 40px 0 30px;
    text-align: center;
    line-height: 1.4;
}

#wemd h1 .content {
    font-size: 22px;
    font-weight: bold;
    color: #000;
}

#wemd h1 .prefix,
#wemd h1 .suffix {
    display: none;
}

/* 二级标题 - 章节 Section */
#wemd h2 {
    margin: 30px 0 15px;
    text-align: left;
    border-bottom: 2px solid #000;
    /* 加粗底线 */
    padding-bottom: 8px;
}

#wemd h2 .content {
    font-size: 18px;
    font-weight: bold;
    color: #000;
}

#wemd h2 .prefix,
#wemd h2 .suffix {
    display: none;
}

/* 三级标题 - Subsection */
#wemd h3 {
    margin: 20px 0 10px;
}

#wemd h3 .content {
    font-size: 16px;
    font-weight: bold;
    color: #800000;
    /* 栗色，区分层级 */
}

#wemd h3 .prefix,
#wemd h3 .suffix {
    display: none;
}

/* 四级标题 */
#wemd h4 {
    margin: 15px 0 5px;
}

#wemd h4 .content {
    font-size: 16px;
    font-weight: bold;
    font-style: italic;
    /* 斜体标题 */
    color: #333;
}

#wemd h4 .prefix,
#wemd h4 .suffix {
    display: none;
}

/* 引用 - 简洁边框 */
#wemd .multiquote-1 {
    margin: 20px 0;
    padding: 16px 20px;
    background: #fafafa;
    border: 1px solid #ddd;
    border-left: 4px solid #666;
}

#wemd .multiquote-1 p {
    color: #555;
    font-size: 15px;
    margin: 0;
    line-height: 1.6;
    text-indent: 0;
}

#wemd .multiquote-2 {
    margin: 18px 0 18px 20px;
    padding: 14px 18px;
    background: #fafafa;
    border: 1px solid #ddd;
}

#wemd .multiquote-2 p {
    color: #555;
    font-size: 15px;
    margin: 0;
}

#wemd .multiquote-3 {
    margin: 16px 0 16px 20px;
    padding: 12px 16px;
    background: #fcfcfc;
    border: 1px solid #e0e0e0;
}

#wemd .multiquote-3 p {
    color: #555;
    font-size: 15px;
    margin: 0;
}

/* 列表 */
#wemd ul {
    list-style: disc;
    padding-left: 20px;
    margin: 16px 0;
}

#wemd ul ul {
    list-style-type: square;
    margin-top: 5px;
}

#wemd ol {
    list-style: decimal;
    padding-left: 20px;
    margin: 16px 0;
}

#wemd ol ol {
    list-style-type: lower-alpha;
}

#wemd li section {
    color: #333;
    line-height: 1.6;
}

/* 链接 - 经典深蓝 */
#wemd a {
    color: #000080;
    text-decoration: underline;
}

/* 加粗 */
#wemd strong {
    color: #000;
    font-weight: bold;
}

/* 斜体 */
#wemd em {
    font-style: italic;
    color: #000;
}

/* 加粗斜体 */
#wemd em strong {
    font-weight: bold;
    font-style: italic;
    color: #000;
}

/* 高亮 - 学术标记风格 */
#wemd mark {
    background: #fff3cd;
    color: #000;
    padding: 0 2px;
}

/* 删除线 */
#wemd del {
    text-decoration: line-through;
    color: #666;
    opacity: 0.7;
}

/* 图片 - 简洁无装饰 */
#wemd img {
    display: block;
    margin: 30px auto;
    width: 100%;
    border: 1px solid #ddd;
}

#wemd figcaption {
    margin-top: 8px;
    text-align: center;
    color: #666;
    font-size: 14px;
    font-style: italic;
}

/* 
 * 行内代码 - LaTeX 	exttt 风格 (修复重点)
 * 纯黑文字 + 极淡灰底 + 等宽字体
 */
#wemd p code,
#wemd li code {
    color: #000;
    /* 纯黑 */
    background: #f4f4f4;
    /* 极淡灰 */
    border: 1px solid #eee;
    /* 极细边框 */
    padding: 1px 4px;
    margin: 0 2px;
    border-radius: 2px;
    font-size: 14px;
    font-family: "Courier New", Courier, monospace;
    /* 强制等宽 */
}

/* 代码块 - 简单的学术风格 */
/* 注意：不要设置 color，让语法高亮主题控制文字颜色 */
#wemd pre code.hljs {
    background: #f9f9f9;
    border: 1px solid #ccc;
    /* color 由 .hljs 语法高亮主题控制 */
    font-family: "Courier New", monospace;
    font-size: 13px;
    padding: 12px;
    border-radius: 0;
    /* 直角 */
    overflow-x: auto;
    white-space: pre;
  min-width: max-content;
}

/* 如果没有语法高亮，设置默认颜色 */
#wemd pre code:not(.hljs) {
    color: #333;
}

/* 表格 - 经典三线表 */
#wemd table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-size: 14px;
    border-top: 2px solid #000;
    border-bottom: 2px solid #000;
}

#wemd table tr th {
    border-bottom: 1px solid #000;
    padding: 10px 5px;
    font-weight: bold;
    text-align: center;
    background: #fff;
}

#wemd table tr td {
    padding: 10px 5px;
    border: none;
    text-align: center;
    color: #333;
}

/* 隔行微底色 */
#wemd table tr:nth-child(even) td {
    background-color: #fafafa;
}

/* 脚注 */
#wemd .footnote-word,
#wemd .footnote-ref {
    color: #000080;
}

#wemd .footnotes-sep {
    border-top: 1px solid #ccc;
    padding-top: 10px;
    margin-top: 40px;
    width: 20%;
    /* 短线 */
}

#wemd .footnote-num {
    font-weight: bold;
    color: #000;
    margin-right: 4px;
    vertical-align: super;
    font-size: 10px;
}

#wemd .footnote-item p {
    color: #666;
    font-size: 12px;
    margin: 4px 0;
}

/* 公式 */
#wemd .block-equation > svg {
    max-width: 100% !important;
}

#wemd .inline-equation > svg {
    max-width: 100%;
    vertical-align: middle;
}

/* 提示块 - 学术风格 */
#wemd .callout {
    margin: 20px 0;
    padding: 16px 20px;
    border: 1px solid #ddd;
    border-radius: 0;
    background: #fafafa;
}

#wemd .callout-title {
    font-weight: bold;
    margin-bottom: 8px;
    font-size: 14px;
    text-transform: uppercase;
    color: #000;
}

#wemd .callout-icon { margin-right: 8px;
    margin-right: 6px;
}

#wemd .callout-note { 
    border-left: 4px solid #666; 
    background: #f5f5f5;
}

#wemd .callout-tip { 
    border-left: 4px solid #555; 
    background: #f5f5f5;
}

#wemd .callout-important { 
    border-left: 4px solid #888; 
    background: #f5f5f5;
}

#wemd .callout-warning { 
    border-left: 4px solid #999; 
    background: #f5f5f5;
}

#wemd .callout-caution { 
    border-left: 4px solid #000; 
    background: #f5f5f5;
}

/* Imageflow CSS */
#wemd .imageflow-layer1 {
  margin-top: 1em;
  margin-bottom: 0.5em;
  /* white-space: normal; */
  border: 0px none;
  padding: 0px;
  overflow: hidden;
}

#wemd .imageflow-layer2 {
  white-space: nowrap;
  width: 100%;
  overflow-x: scroll;
}

#wemd .imageflow-layer3 {
  display: inline-block;
  word-wrap: break-word;
  white-space: normal;
  vertical-align: top;
  width: 80%;
  margin-right: 10px;
  flex-shrink: 0;
}

#wemd .imageflow-img {
  display: block;
  width: 100%;
  height: auto;
  max-height: 300px;
  object-fit: contain;
  border-radius: 4px;
}

#wemd .imageflow-caption {
  text-align: center;
  margin-top: 0px;
  padding-top: 0px;
  color: #888;
}

/*
github.com style (c) Vasily Polovnyov <vast@whiteants.net>
*/

/* 代码块样式 - 需要添加 #wemd 前缀以匹配包装后的 HTML */
#wemd .hljs {
  display: block;
  overflow-x: auto;
  padding: 16px;
  color: #333;
  background: #f8f8f8;
}

#wemd .hljs-comment,
#wemd .hljs-quote {
  color: #998;
  font-style: italic;
}

#wemd .hljs-keyword,
#wemd .hljs-selector-tag,
#wemd .hljs-subst {
  color: #333;
  font-weight: bold;
}

#wemd .hljs-number,
#wemd .hljs-literal,
#wemd .hljs-variable,
#wemd .hljs-template-variable,
#wemd .hljs-tag .hljs-attr {
  color: #008080;
}

#wemd .hljs-string,
#wemd .hljs-doctag {
  color: #d14;
}

#wemd .hljs-title,
#wemd .hljs-section,
#wemd .hljs-selector-id {
  color: #900;
  font-weight: bold;
}

#wemd .hljs-subst {
  font-weight: normal;
}

#wemd .hljs-type,
#wemd .hljs-class .hljs-title {
  color: #458;
  font-weight: bold;
}

#wemd .hljs-tag,
#wemd .hljs-name,
#wemd .hljs-attribute {
  color: #000080;
  font-weight: normal;
}

#wemd .hljs-regexp,
#wemd .hljs-link {
  color: #009926;
}

#wemd .hljs-symbol,
#wemd .hljs-bullet {
  color: #990073;
}

#wemd .hljs-built_in,
#wemd .hljs-builtin-name {
  color: #0086b3;
}

#wemd .hljs-meta {
  color: #999;
  font-weight: bold;
}

#wemd .hljs-deletion {
  background: #fdd;
}

#wemd .hljs-addition {
  background: #dfd;
}

#wemd .hljs-emphasis {
  font-style: italic;
}

#wemd .hljs-strong {
  font-weight: bold;
}

/* Imageflow CSS */
#wemd .imageflow-layer1 {
  margin-top: 1em;
  margin-bottom: 0.5em;
  /* white-space: normal; */
  border: 0px none;
  padding: 0px;
  overflow: hidden;
}

#wemd .imageflow-layer2 {
  white-space: nowrap;
  width: 100%;
  overflow-x: scroll;
}

#wemd .imageflow-layer3 {
  display: inline-block;
  word-wrap: break-word;
  white-space: normal;
  vertical-align: top;
  width: 80%;
  margin-right: 10px;
  flex-shrink: 0;
}

#wemd .imageflow-img {
  display: block;
  width: 100%;
  height: auto;
  max-height: 300px;
  object-fit: contain;
  border-radius: 4px;
}

#wemd .imageflow-caption {
  text-align: center;
  margin-top: 0px;
  padding-top: 0px;
  color: #888;
}

/* ========================================
   微信公众号兼容修正：无序列表字号固定为 16px
   ======================================== */
#wemd ul,
#wemd ul li,
#wemd ul li section,
#wemd ul li p {
    font-size: 16px !important;
}
